$env:PYTHONIOENCODING='utf-8'
try {
  $r = Invoke-RestMethod 'http://127.0.0.1:18098/api/state' -TimeoutSec 30
  $acctItems = @($r.items | Where-Object { $_.accounts -and $_.accounts.Count -gt 0 })
  Write-Output "items=$($r.items.Count) items_with_accounts=$($acctItems.Count)"
  foreach ($it in $acctItems | Select-Object -First 6) {
    Write-Output ("- {0}/{1}: {2}" -f $it.project, $it.env, (($it.accounts | ForEach-Object { $_.role + '=' + $_.username + '/' + $(if($_.hasSecret){'hasSecret'}else{'noSecret'}) }) -join ', '))
  }
} catch { Write-Output "STATE_ERR=$($_.Exception.Message)" }

$env:PYTHONIOENCODING='utf-8'
try {
  $r = Invoke-RestMethod 'http://127.0.0.1:18098/api/state' -TimeoutSec 30
  $it = $r.items | Where-Object { $_.project_key -eq 'fdc-v3' -and $_.env -eq 'local' } | Select-Object -First 1
  if (-not $it) { Write-Output 'ITEM_NOT_FOUND'; Write-Output (($r.items | Select-Object -First 1) | ConvertTo-Json -Depth 4 -Compress); exit }
  Write-Output ("fields=" + (($it.PSObject.Properties.Name) -join ','))
  Write-Output ("accounts_type=" + $it.accounts.GetType().Name + " count=" + @($it.accounts).Count)
  Write-Output ($it.accounts | ConvertTo-Json -Depth 4 -Compress)
} catch { Write-Output "ERR=$($_.Exception.Message)" }

