# -*- coding: utf-8 -*-
"""从进程环境读取已解析的密码，注入看板进程内存。明文不落盘，仅存于环境变量与本机 HTTP 请求。"""
import json, urllib.request, os, sqlite3

DASH = r'D:\repository\skills\deploy-env\dashboard'
BASE = 'http://127.0.0.1:18098'

def token():
    with open(os.path.join(DASH, '.token'), 'r', encoding='utf-8') as f:
        return f.read().strip()

def post(path, body):
    data = json.dumps(body).encode('utf-8')
    req = urllib.request.Request(BASE + path, data=data, method='POST',
        headers={'Content-Type': 'application/json', 'X-Auth-Token': token()})
    with urllib.request.urlopen(req, timeout=10) as r:
        return json.loads(r.read().decode('utf-8'))

pwd = {
    'deploy_env-pwd-super': os.environ['DPWD_SUPER'],
    'deploy_env-pwd-county': os.environ['DPWD_COUNTY'],
    'deploy_env-pwd-fangxun': os.environ['DPWD_FANGXUN'],
}
REF = {
    'deploy_env-pwd-super': '{{ov_privacy:default:viking://~/privacy/credential/deploy_env-pwd-super#/values/password}}',
    'deploy_env-pwd-county': '{{ov_privacy:default:viking://~/privacy/credential/deploy_env-pwd-county#/values/password}}',
    'deploy_env-pwd-fangxun': '{{ov_privacy:default:viking://~/privacy/credential/deploy_env-pwd-fangxun#/values/password}}',
}

ACCTS = []
for env in ['local', 'dev', 'test', 'uat', 'prod', 'local-8098']:
    ACCTS.append(('fdc-v3', env, 'admin', 'deploy_env-pwd-super'))
    ACCTS.append(('fdc-v3', env, 'operator', 'deploy_env-pwd-county'))
ACCTS.append(('防汛C端', 'test', 'admin', 'deploy_env-pwd-fangxun'))
for key, env in [('惠山二期G','local'), ('无锡市区G','test'), ('江阴公共收益','test'), ('泰兴G','test'), ('淮安物管','test')]:
    ACCTS.append((key, env, 'admin', 'deploy_env-pwd-super'))
    ACCTS.append((key, env, 'operator', 'deploy_env-pwd-county'))

con = sqlite3.connect(r'D:\repository\skills\deploy-env\registry.sqlite')
for k, e, r, pkey in ACCTS:
    row = con.execute('SELECT secret_ref FROM env_accounts WHERE project_key=? AND env=? AND role=?', (k, e, r)).fetchone()
    if not row or row[0].strip() != REF[pkey]:
        raise SystemExit(f'SECRET_REF_MISMATCH {k}/{e}/{r}: {row}')
con.close()

ok = 0
for k, e, r, pkey in ACCTS:
    res = post('/api/secrets/inject', {'project_key': k, 'env': e, 'role': r, 'password': pwd[pkey]})
    if not res.get('ok'):
        raise SystemExit(f'INJECT_FAIL {k}/{e}/{r}: {res}')
    ok += 1

chk = post('/api/account/reveal', {'project_key': 'fdc-v3', 'env': 'local', 'role': 'admin'})
print(f'INJECTED={ok} REVEAL_OK={chk.get("ok")} LEN={len(chk.get("password", ""))}')

